+func runSemanticSnapshot(ctx context.Context, runner CommandRunner, repoDir, semBinary string) ([]byte, error) {
+	stdout, _, err := runner.Run(ctx, repoDir, semBinary, "sem", "snapshot", "--repo", repoDir, "--format", "ndjson", "--no-network")
